// Variables used by Scriptable.
// These must be at the very top of the file. Do not edit.
// icon-color: deep-blue; icon-glyph: th-large;
/*
 * Подсказчик Block Blast для iPhone (приложение Scriptable).
 * Запуск: быстрая команда «Снимок экрана → Run Script (этот скрипт) → Быстрый просмотр»,
 * повешенная на двойное касание задней панели. Подробности: README.md, раздел iPhone.
 *
 * Файл собран из ios/template.js скриптом ios/build.js — правьте исходники, а не его.
 */
const FM = FileManager.local();
const CFG_PATH = FM.joinPath(FM.documentsDirectory(), 'blockblast-calib.json');

async function say(title, message) {
  const a = new Alert();
  a.title = title; a.message = message; a.addAction('OK');
  await a.present();
}
function loadCalib() {
  if (!FM.fileExists(CFG_PATH)) return null;
  try { return JSON.parse(FM.readString(CFG_PATH)); } catch (e) { return null; }
}
function saveCalib(c) { FM.writeString(CFG_PATH, JSON.stringify(c)); }

async function main() {
  const images = (args.images || []).filter(Boolean);

  // Run inside the Scriptable app: import settings copied from the hint page.
  if (config.runsInApp && !images.length) {
    let clip = '';
    try { clip = Pasteboard.paste() || ''; } catch (e) {}
    let c = null;
    try { c = JSON.parse(clip); } catch (e) {}
    if (c && c.grid && c.tray) {
      saveCalib(c);
      await say('Настройки сохранены', 'Теперь в игре дважды коснитесь задней панели iPhone, чтобы увидеть подсказку.');
      return;
    }
    if (!loadCalib()) {
      await say('Нужны настройки рамок', 'Откройте страницу подсказчика, загрузите один скриншот игры, подгоните рамки и нажмите «Копировать настройки». Затем снова запустите этот скрипт.');
      return;
    }
    // Test run from the app: use the latest screenshot from Photos.
    const shot = await Photos.latestScreenshot();
    if (!shot) { await say('Нет скриншота', 'Для проверки сделайте один скриншот игры.'); return; }
    const out = await analyse(shot, loadCalib());
    if (out) await QuickLook.present(out, true);
    return;
  }

  const calib = loadCalib();
  if (!calib) {
    await say('Нужны настройки рамок', 'Откройте скрипт BlockBlast в приложении Scriptable и следуйте подсказке.');
    return;
  }
  if (!images.length) {
    await say('Нет снимка экрана', 'В быстрой команде первым действием должен быть «Снимок экрана», а его результат передайте в поле Images.');
    return;
  }
  const out = await analyse(images[0], calib);
  if (out) Script.setShortcutOutput(out);
}

async function analyse(image, calib) {
  const b64 = Data.fromJPEG(image).toBase64String();
  const wv = new WebView();
  await wv.loadHTML(HTML);
  const js = `BBOverlay.run('data:image/jpeg;base64,${b64}', ${JSON.stringify(calib)})` +
    `.then(function (r) { completion(r); }, function (e) { completion({ error: String(e) }); });`;
  const res = await wv.evaluateJavaScript(js, true);
  if (!res || res.error) { await say('Ошибка', String(res && res.error)); return null; }
  if (res.learnedRatio && !calib.trayCellRatio) { calib.trayCellRatio = res.learnedRatio; saveCalib(calib); }
  return Image.fromData(Data.fromBase64String(res.img.split(',')[1]));
}

const HTML = "<!doctype html><html><head><meta charset=\"utf-8\"></head><body><script>\n/*\n * Block Blast solver.\n * Works in the browser (window.BlockSolver) and in Node (require('./solver')).\n *\n * Board: 8x8, cell index i = row*8 + col.\n * Stored as two 32-bit masks: lo = rows 0..3, hi = rows 4..7.\n */\n(function (root, factory) {\n  if (typeof module === 'object' && module.exports) module.exports = factory();\n  else root.BlockSolver = factory();\n})(typeof self !== 'undefined' ? self : this, function () {\n  'use strict';\n\n  const N = 8;\n\n  // ---------- shapes ----------\n  function normalize(cells) {\n    let mr = Infinity, mc = Infinity;\n    for (const [r, c] of cells) { if (r < mr) mr = r; if (c < mc) mc = c; }\n    return cells.map(([r, c]) => [r - mr, c - mc]).sort((a, b) => a[0] - b[0] || a[1] - b[1]);\n  }\n  function parseShape(str) {\n    const cells = [];\n    str.split('/').forEach((row, r) => {\n      [...row].forEach((ch, c) => { if (ch === 'X') cells.push([r, c]); });\n    });\n    return normalize(cells);\n  }\n  function shapeKey(cells) { return normalize(cells).map((x) => x[0] + ',' + x[1]).join(';'); }\n  function dims(cells) {\n    let h = 0, w = 0;\n    for (const [r, c] of cells) { if (r + 1 > h) h = r + 1; if (c + 1 > w) w = c + 1; }\n    return [h, w];\n  }\n  function rotate(cells) { return normalize(cells.map(([r, c]) => [c, -r])); }\n  function mirror(cells) { return normalize(cells.map(([r, c]) => [r, -c])); }\n  function variants(cells, withMirror) {\n    const out = new Map();\n    let cur = normalize(cells);\n    for (let m = 0; m < (withMirror ? 2 : 1); m++) {\n      for (let k = 0; k < 4; k++) { out.set(shapeKey(cur), cur); cur = rotate(cur); }\n      cur = mirror(cur);\n    }\n    return [...out.values()];\n  }\n\n  // Block Blast piece set (all rotations).\n  const BASES = [\n    ['X', false], ['XX', false], ['XXX', false], ['XXXX', false], ['XXXXX', false],\n    ['XX/XX', false], ['XXX/XXX', false], ['XXX/XXX/XXX', false],\n    ['XX/X.', false], ['XXX/X../X..', false],\n    ['XXX/X..', true], ['XXX/.X.', false], ['XX./.XX', true],\n    ['X./.X', false], ['X../.X./..X', false],\n  ];\n  const SHAPES = [];\n  {\n    const seen = new Set();\n    for (const [s, mir] of BASES) {\n      for (const v of variants(parseShape(s), mir)) {\n        const k = shapeKey(v);\n        if (!seen.has(k)) { seen.add(k); SHAPES.push(v); }\n      }\n    }\n  }\n\n  // ---------- bit masks ----------\n  function cellBit(idx) {\n    return idx < 32 ? [(1 << idx) >>> 0, 0] : [0, (1 << (idx - 32)) >>> 0];\n  }\n  const LINES = [];\n  for (let r = 0; r < N; r++) {\n    const m = (0xff << (8 * (r % 4))) >>> 0;\n    LINES.push(r < 4 ? { lo: m, hi: 0 } : { lo: 0, hi: m });\n  }\n  for (let c = 0; c < N; c++) {\n    const m = (0x01010101 << c) >>> 0;\n    LINES.push({ lo: m, hi: m });\n  }\n\n  const placementCache = new Map();\n  function placementsFor(cells) {\n    const key = shapeKey(cells);\n    let pl = placementCache.get(key);\n    if (pl) return pl;\n    const norm = normalize(cells);\n    const [h, w] = dims(norm);\n    pl = [];\n    for (let r0 = 0; r0 + h <= N; r0++) {\n      for (let c0 = 0; c0 + w <= N; c0++) {\n        let lo = 0, hi = 0;\n        for (const [r, c] of norm) {\n          const [a, b] = cellBit((r0 + r) * N + c0 + c);\n          lo |= a; hi |= b;\n        }\n        pl.push({ r: r0, c: c0, lo: lo >>> 0, hi: hi >>> 0, n: norm.length });\n      }\n    }\n    placementCache.set(key, pl);\n    return pl;\n  }\n\n  function boardToMasks(board) {\n    if (board && typeof board.lo === 'number') return board;\n    let lo = 0, hi = 0;\n    for (let i = 0; i < 64; i++) {\n      if (board[i]) { const [a, b] = cellBit(i); lo |= a; hi |= b; }\n    }\n    return { lo: lo >>> 0, hi: hi >>> 0 };\n  }\n  function masksToBoard(lo, hi) {\n    const b = new Array(64);\n    for (let i = 0; i < 32; i++) { b[i] = (lo >>> i) & 1; b[32 + i] = (hi >>> i) & 1; }\n    return b;\n  }\n\n  // Place piece and clear full lines. Result written into OUT to avoid allocations.\n  const OUT = { lo: 0, hi: 0, n: 0, clo: 0, chi: 0 };\n  function applyPlace(lo, hi, p) {\n    lo = (lo | p.lo) >>> 0; hi = (hi | p.hi) >>> 0;\n    let clo = 0, chi = 0, n = 0;\n    for (let k = 0; k < 16; k++) {\n      const L = LINES[k];\n      if (((lo & L.lo) >>> 0) === L.lo && ((hi & L.hi) >>> 0) === L.hi) { clo |= L.lo; chi |= L.hi; n++; }\n    }\n    OUT.lo = (lo & ~clo) >>> 0; OUT.hi = (hi & ~chi) >>> 0; OUT.n = n;\n    OUT.clo = clo >>> 0; OUT.chi = chi >>> 0;\n    return OUT;\n  }\n\n  // ---------- evaluation ----------\n  // Tuned with sim.js on random games (avg survival ~103 -> ~124 rounds on held-out seeds).\n  const DEFAULT_WEIGHTS = {\n    reward: 1.0,   // points for clears/combo during this turn\n    empty: 1.0,    // each free cell\n    hole: 3.5,     // isolated single free cell\n    trans: 3.2,    // filled/empty transitions (roughness)\n    fit: 1.5,      // multiplier for \"big pieces still fit\" bonus\n    noFit: 12.5,   // multiplier for penalty when a big piece does not fit anywhere\n    combo: 3.0,    // value of keeping an active combo\n  };\n\n  // Test pieces: [shape, importance]\n  const TESTS = [\n    ['XXX/XXX/XXX', 1.5], ['XXXXX', 1.0], ['X/X/X/X/X', 1.0],\n    ['XXX/XXX', 0.6], ['XX/XX/XX', 0.6],\n    ['XXX/X../X..', 0.5], ['XXX/..X/..X', 0.5], ['X../X../XXX', 0.5], ['..X/..X/XXX', 0.5],\n    ['XXXX', 0.4], ['X/X/X/X', 0.4], ['XX/XX', 0.4],\n  ].map(([s, w]) => ({ pl: placementsFor(parseShape(s)), w }));\n\n  const G = new Uint8Array(64);\n  function cheapEval(lo, hi, W) {\n    for (let i = 0; i < 32; i++) { G[i] = (lo >>> i) & 1; G[32 + i] = (hi >>> i) & 1; }\n    let empty = 0, holes = 0, trans = 0;\n    for (let r = 0; r < N; r++) {\n      let prev = 1;\n      for (let c = 0; c < N; c++) {\n        const v = G[r * N + c];\n        if (v !== prev) trans++;\n        prev = v;\n        if (!v) {\n          empty++;\n          if ((r === 0 || G[(r - 1) * N + c]) && (r === N - 1 || G[(r + 1) * N + c]) &&\n              (c === 0 || G[r * N + c - 1]) && (c === N - 1 || G[r * N + c + 1])) holes++;\n        }\n      }\n      if (prev !== 1) trans++;\n    }\n    for (let c = 0; c < N; c++) {\n      let prev = 1;\n      for (let r = 0; r < N; r++) {\n        const v = G[r * N + c];\n        if (v !== prev) trans++;\n        prev = v;\n      }\n      if (prev !== 1) trans++;\n    }\n    return W.empty * empty - W.hole * holes - W.trans * trans;\n  }\n  function fitEval(lo, hi, W) {\n    let s = 0;\n    for (const t of TESTS) {\n      let cnt = 0;\n      const pl = t.pl;\n      for (let k = 0; k < pl.length; k++) {\n        const p = pl[k];\n        if (((lo & p.lo) | (hi & p.hi)) === 0) cnt++;\n      }\n      s += t.w * (W.fit * Math.log2(1 + cnt) - (cnt === 0 ? W.noFit : 0));\n    }\n    return s;\n  }\n  function comboValue(combo, since, W) {\n    return combo > 0 ? W.combo * combo * (3 - since) / 3 : 0;\n  }\n\n  // ---------- search ----------\n  /**\n   * board: array[64] of 0/1 (or {lo,hi})\n   * pieces: array (up to 3) of cell lists [[r,c],...] or null for already-used slots\n   * opts.state: {combo, since} carried between turns\n   * returns { moves:[{piece,r,c,cells,lines,clearedCells,boardAfter}], placedAll, gameOver, state, lines }\n   */\n  function solve(board, pieces, opts) {\n    opts = opts || {};\n    const W = Object.assign({}, DEFAULT_WEIGHTS, opts.weights || {});\n    const topK = opts.topK || 2000;\n    const st0 = opts.state || { combo: 0, since: 0 };\n    const { lo: lo0, hi: hi0 } = boardToMasks(board);\n\n    const idxs = [];\n    const PL = [];\n    pieces.forEach((p, i) => {\n      if (p && p.length) { idxs.push(i); PL[i] = placementsFor(p); }\n    });\n    if (!idxs.length) return { moves: [], placedAll: true, gameOver: false, state: st0, lines: 0 };\n\n    let remAll = 0;\n    for (const i of idxs) remAll |= 1 << i;\n\n    const root = { lo: lo0, hi: hi0, combo: st0.combo, since: st0.since, rem: remAll, reward: 0, parent: null, move: null };\n    let cur = [root];\n    let deepest = [root];\n    const k = idxs.length;\n\n    // Final-level candidates in parallel arrays (no per-candidate objects).\n    const fLo = [], fHi = [], fCombo = [], fSince = [], fReward = [], fCheap = [], fParent = [], fPiece = [], fPl = [];\n\n    for (let d = 0; d < k; d++) {\n      const isLast = d === k - 1;\n      const next = new Map();\n      for (const s of cur) {\n        for (const i of idxs) {\n          if (!((s.rem >> i) & 1)) continue;\n          const pls = PL[i];\n          for (let pi = 0; pi < pls.length; pi++) {\n            const p = pls[pi];\n            if ((s.lo & p.lo) | (s.hi & p.hi)) continue;\n            const o = applyPlace(s.lo, s.hi, p);\n            let combo = s.combo, since = s.since, reward = s.reward + p.n;\n            if (o.n > 0) { combo++; since = 0; reward += 10 * (o.n * o.n + o.n * (combo - 1)); }\n            else { since++; if (since >= 3) combo = 0; }\n            if (isLast) {\n              fLo.push(o.lo); fHi.push(o.hi); fCombo.push(combo); fSince.push(since);\n              fReward.push(reward); fCheap.push(reward * W.reward + cheapEval(o.lo, o.hi, W) + comboValue(combo, since, W));\n              fParent.push(s); fPiece.push(i); fPl.push(pi);\n            } else {\n              const rem = s.rem & ~(1 << i);\n              const key = rem + ':' + o.lo + ':' + o.hi + ':' + combo + ':' + since;\n              const ex = next.get(key);\n              if (!ex || ex.reward < reward) {\n                next.set(key, { lo: o.lo, hi: o.hi, combo, since, rem, reward, parent: s, move: { piece: i, pi } });\n              }\n            }\n          }\n        }\n      }\n      if (isLast) break;\n      if (next.size === 0) break;\n      cur = [...next.values()];\n      deepest = cur;\n    }\n\n    let best = null, bestScore = -Infinity;\n    if (fLo.length) {\n      const order = Array.from(fLo.keys());\n      if (order.length > topK) {\n        order.sort((a, b) => fCheap[b] - fCheap[a]);\n        order.length = topK;\n      }\n      for (const j of order) {\n        const sc = fCheap[j] + fitEval(fLo[j], fHi[j], W);\n        if (sc > bestScore) { bestScore = sc; best = j; }\n      }\n      const leaf = { lo: fLo[best], hi: fHi[best], combo: fCombo[best], since: fSince[best], reward: fReward[best], parent: fParent[best], move: { piece: fPiece[best], pi: fPl[best] } };\n      return build(leaf, true, bestScore);\n    }\n\n    // Could not place every piece: choose best among the deepest reachable states.\n    if (deepest[0] === root) {\n      return { moves: [], placedAll: false, gameOver: true, state: st0, lines: 0, score: -Infinity };\n    }\n    for (const s of deepest) {\n      const sc = s.reward * W.reward + cheapEval(s.lo, s.hi, W) + fitEval(s.lo, s.hi, W);\n      if (sc > bestScore) { bestScore = sc; best = s; }\n    }\n    return build(best, false, bestScore);\n\n    function build(leaf, placedAll, score) {\n      const chain = [];\n      for (let s = leaf; s && s.move; s = s.parent) chain.push(s.move);\n      chain.reverse();\n      let lo = lo0, hi = hi0, lines = 0;\n      const moves = chain.map((m) => {\n        const p = PL[m.piece][m.pi];\n        const before = masksToBoard(lo, hi);\n        const o = applyPlace(lo, hi, p);\n        lo = o.lo; hi = o.hi; lines += o.n;\n        const cells = normalize(pieces[m.piece]).map(([r, c]) => [p.r + r, p.c + c]);\n        const cleared = masksToBoard(o.clo, o.chi);\n        return {\n          piece: m.piece, r: p.r, c: p.c, cells, lines: o.n,\n          clearedCells: cleared.map((v, i) => (v ? i : -1)).filter((i) => i >= 0),\n          boardBefore: before, boardAfter: masksToBoard(lo, hi),\n        };\n      });\n      return {\n        moves, placedAll, gameOver: !placedAll, lines, score,\n        state: { combo: leaf.combo, since: leaf.since },\n      };\n    }\n  }\n\n  return {\n    N, SHAPES, solve, parseShape, normalize, shapeKey, dims, placementsFor,\n    boardToMasks, masksToBoard, applyPlace, DEFAULT_WEIGHTS,\n  };\n});\n\n</script>\n<script>\n/*\n * Screenshot recognition for Block Blast.\n * img: { width, height, data } with RGBA bytes (browser ImageData or pngjs PNG).\n * calib: { grid: {x,y,w,h}, tray: {x,y,w,h}, trayCellRatio?: number }  (pixel coordinates)\n */\n(function (root, factory) {\n  if (typeof module === 'object' && module.exports) module.exports = factory();\n  else root.BlockDetect = factory();\n})(typeof self !== 'undefined' ? self : this, function () {\n  'use strict';\n\n  function avgColor(img, x0, y0, x1, y1) {\n    x0 = Math.max(0, Math.round(x0)); y0 = Math.max(0, Math.round(y0));\n    x1 = Math.min(img.width, Math.round(x1)); y1 = Math.min(img.height, Math.round(y1));\n    let r = 0, g = 0, b = 0, n = 0;\n    for (let y = y0; y < y1; y++) {\n      for (let x = x0; x < x1; x++) {\n        const i = (y * img.width + x) * 4;\n        r += img.data[i]; g += img.data[i + 1]; b += img.data[i + 2]; n++;\n      }\n    }\n    return n ? [r / n, g / n, b / n] : [0, 0, 0];\n  }\n  const dist = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);\n  const lum = (c) => 0.299 * c[0] + 0.587 * c[1] + 0.114 * c[2];\n\n  function detectBoard(img, grid, threshold) {\n    threshold = threshold || 60;\n    const cw = grid.w / 8, ch = grid.h / 8;\n    const colors = [];\n    for (let r = 0; r < 8; r++) {\n      for (let c = 0; c < 8; c++) {\n        const cx = grid.x + (c + 0.5) * cw, cy = grid.y + (r + 0.5) * ch;\n        colors.push(avgColor(img, cx - cw * 0.2, cy - ch * 0.2, cx + cw * 0.2, cy + ch * 0.2));\n      }\n    }\n    // Empty reference: median of the darkest quarter of cells.\n    const sorted = colors.slice().sort((a, b) => lum(a) - lum(b));\n    const dark = sorted.slice(0, 8);\n    const ref = [0, 1, 2].map((k) => dark.map((c) => c[k]).sort((a, b) => a - b)[4]);\n    const board = colors.map((c) => (dist(c, ref) > threshold && lum(c) > lum(ref) ? 1 : 0));\n    return { board, emptyRef: ref };\n  }\n\n  function detectTray(img, tray, gridCell, opts) {\n    opts = opts || {};\n    const threshold = opts.threshold || 70;\n    const step = Math.max(1, Math.round(Math.min(tray.w, tray.h) / 200));\n    // Background reference from the tray's corners.\n    const pw = tray.w * 0.04, ph = tray.h * 0.08;\n    const corners = [\n      avgColor(img, tray.x, tray.y, tray.x + pw, tray.y + ph),\n      avgColor(img, tray.x + tray.w - pw, tray.y, tray.x + tray.w, tray.y + ph),\n      avgColor(img, tray.x, tray.y + tray.h - ph, tray.x + pw, tray.y + tray.h),\n      avgColor(img, tray.x + tray.w - pw, tray.y + tray.h - ph, tray.x + tray.w, tray.y + tray.h),\n    ];\n    const bg = [0, 1, 2].map((k) => corners.map((c) => c[k]).sort((a, b) => a - b)[1]);\n\n    const isPiece = (x, y) => {\n      const i = (y * img.width + x) * 4;\n      const c = [img.data[i], img.data[i + 1], img.data[i + 2]];\n      return dist(c, bg) > threshold;\n    };\n\n    // Bounding box of piece pixels in each third of the tray.\n    const slots = [];\n    for (let s = 0; s < 3; s++) {\n      const x0 = Math.round(tray.x + (tray.w * s) / 3), x1 = Math.round(tray.x + (tray.w * (s + 1)) / 3);\n      let minX = Infinity, minY = Infinity, maxX = -1, maxY = -1, cnt = 0;\n      for (let y = Math.round(tray.y); y < tray.y + tray.h; y += step) {\n        for (let x = x0; x < x1; x += step) {\n          if (isPiece(x, y)) {\n            cnt++;\n            if (x < minX) minX = x; if (x > maxX) maxX = x;\n            if (y < minY) minY = y; if (y > maxY) maxY = y;\n          }\n        }\n      }\n      const minPixels = ((gridCell * 0.25) / step) ** 2;\n      slots.push(cnt > minPixels ? { x: minX, y: minY, w: maxX - minX + step, h: maxY - minY + step } : null);\n    }\n\n    // Common cell size for all tray pieces.\n    let size;\n    if (opts.trayCellRatio) size = gridCell * opts.trayCellRatio;\n    else {\n      const boxes = slots.filter(Boolean);\n      if (!boxes.length) return { pieces: [null, null, null], slots, cellSize: 0, bg };\n      let bestErr = Infinity;\n      const cands = [];\n      for (let s = gridCell * 0.3; s <= gridCell * 1.05; s += 0.5) {\n        let err = 0, ok = true;\n        for (const b of boxes) {\n          const nw = Math.round(b.w / s), nh = Math.round(b.h / s);\n          if (nw < 1 || nh < 1 || nw > 5 || nh > 5) { ok = false; break; }\n          err += Math.abs(b.w - nw * s) / s + Math.abs(b.h - nh * s) / s;\n        }\n        if (!ok) continue;\n        cands.push([s, err]);\n        if (err < bestErr) bestErr = err;\n      }\n      if (!cands.length) return { pieces: [null, null, null], slots, cellSize: 0, bg };\n      // Prefer the largest size whose error is close to the best one.\n      size = cands.filter(([, e]) => e <= bestErr + 0.15 * boxes.length).sort((a, b) => b[0] - a[0])[0][0];\n    }\n\n    const pieces = slots.map((b) => {\n      if (!b) return null;\n      const nw = Math.max(1, Math.min(5, Math.round(b.w / size)));\n      const nh = Math.max(1, Math.min(5, Math.round(b.h / size)));\n      const cw = b.w / nw, chh = b.h / nh;\n      const cells = [];\n      for (let r = 0; r < nh; r++) {\n        for (let c = 0; c < nw; c++) {\n          const cx = b.x + (c + 0.5) * cw, cy = b.y + (r + 0.5) * chh;\n          const col = avgColor(img, cx - cw * 0.2, cy - chh * 0.2, cx + cw * 0.2, cy + chh * 0.2);\n          if (dist(col, bg) > threshold) cells.push([r, c]);\n        }\n      }\n      return cells.length ? cells : null;\n    });\n    return { pieces, slots, cellSize: size, bg };\n  }\n\n  function detect(img, calib) {\n    const b = detectBoard(img, calib.grid, calib.boardThreshold);\n    const t = detectTray(img, calib.tray, calib.grid.w / 8, {\n      trayCellRatio: calib.trayCellRatio, threshold: calib.trayThreshold,\n    });\n    return { board: b.board, pieces: t.pieces, slots: t.slots, trayCellSize: t.cellSize };\n  }\n\n  return { detect, detectBoard, detectTray };\n});\n\n</script>\n<script>\n/*\n * Draws the best moves on top of a Block Blast screenshot.\n * Runs in a browser / WKWebView (used by the Scriptable script for iPhone).\n * Needs BlockSolver (solver.js) and BlockDetect (detect.js) loaded first.\n *\n * BBOverlay.run(imageSrc, calib) -> Promise<{ img (jpeg data URL), text, learnedRatio, ok }>\n * calib: { screen?: {width,height}, grid: {x,y,w,h}, tray: {x,y,w,h}, trayCellRatio? }\n */\n(function (root) {\n  'use strict';\n  const S = root.BlockSolver, D = root.BlockDetect;\n  const COLORS = ['#ffa94d', '#4fd1e8', '#c38bff'];\n  const SLOT = ['Левую', 'Среднюю', 'Правую'];\n  const FONT = '-apple-system, \"SF Pro Display\", system-ui, \"Helvetica Neue\", sans-serif';\n\n  function scaleCalib(c, w, h) {\n    const sx = c.screen ? w / c.screen.width : 1, sy = c.screen ? h / c.screen.height : 1;\n    const sc = (r) => ({ x: r.x * sx, y: r.y * sy, w: r.w * sx, h: r.h * sy });\n    return { grid: sc(c.grid), tray: sc(c.tray), trayCellRatio: c.trayCellRatio };\n  }\n  function loadImg(src) {\n    return new Promise((res, rej) => { const im = new Image(); im.onload = () => res(im); im.onerror = () => rej(new Error('image')); im.src = src; });\n  }\n  function roundRect(g, x, y, w, h, r) {\n    g.beginPath(); g.moveTo(x + r, y); g.arcTo(x + w, y, x + w, y + h, r); g.arcTo(x + w, y + h, x, y + h, r);\n    g.arcTo(x, y + h, x, y, r); g.arcTo(x, y, x + w, y, r); g.closePath();\n  }\n  function badge(g, x, y, r, color, txt) {\n    g.beginPath(); g.arc(x, y, r, 0, Math.PI * 2); g.fillStyle = color; g.fill();\n    g.lineWidth = r * 0.18; g.strokeStyle = '#0b1026'; g.stroke();\n    g.fillStyle = '#0b1026'; g.font = `800 ${Math.round(r * 1.25)}px ${FONT}`;\n    g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(txt, x, y + r * 0.06);\n  }\n\n  async function run(src, calibIn) {\n    const im = await loadImg(src);\n    const W = im.naturalWidth, H = im.naturalHeight;\n    const cv = document.createElement('canvas'); cv.width = W; cv.height = H;\n    const g = cv.getContext('2d');\n    g.drawImage(im, 0, 0);\n    const calib = scaleCalib(calibIn, W, H);\n    const det = D.detect(g.getImageData(0, 0, W, H), calib);\n    const nPieces = det.pieces.filter(Boolean).length;\n    const learnedRatio = !calib.trayCellRatio && nPieces === 3 && det.trayCellSize ? det.trayCellSize / (calib.grid.w / 8) : null;\n    const res = nPieces ? S.solve(det.board, det.pieces) : null;\n\n    const { grid, tray } = calib;\n    const cell = grid.w / 8;\n\n    // Dim everything except the board and the tray.\n    g.fillStyle = 'rgba(5, 8, 22, 0.55)'; g.fillRect(0, 0, W, H);\n    g.drawImage(im, grid.x, grid.y, grid.w, grid.h, grid.x, grid.y, grid.w, grid.h);\n    g.drawImage(im, tray.x, tray.y, tray.w, tray.h, tray.x, tray.y, tray.w, tray.h);\n\n    // Banner above the board.\n    const bannerH = Math.min(cell * 2.3, grid.y * 0.9);\n    const by = Math.max(4, grid.y - bannerH - cell * 0.2);\n    const pad = cell * 0.2;\n    const lines = [];\n\n    if (!res || !res.moves.length) {\n      const msg = !nPieces ? 'Не вижу фигур внизу. Проверьте рамки в настройках.' : 'Ни одна фигура не помещается.';\n      lines.push(msg);\n      g.fillStyle = 'rgba(11,16,38,0.92)'; roundRect(g, pad, by, W - pad * 2, bannerH, cell * 0.25); g.fill();\n      g.fillStyle = '#ff7a8a'; g.font = `700 ${Math.round(cell * 0.38)}px ${FONT}`;\n      g.textAlign = 'center'; g.textBaseline = 'middle'; g.fillText(msg, W / 2, by + bannerH / 2);\n      return { img: cv.toDataURL('image/jpeg', 0.88), text: msg, learnedRatio, ok: false };\n    }\n\n    // Move overlays on the board.\n    res.moves.forEach((m, k) => {\n      g.save();\n      for (const [r, c] of m.cells) {\n        const x = grid.x + c * cell, y = grid.y + r * cell;\n        g.globalAlpha = 0.82; g.fillStyle = COLORS[k];\n        roundRect(g, x + cell * 0.06, y + cell * 0.06, cell * 0.88, cell * 0.88, cell * 0.14); g.fill();\n        g.globalAlpha = 1; g.lineWidth = cell * 0.06; g.strokeStyle = '#ffffff'; g.stroke();\n      }\n      g.restore();\n    });\n    const taken = new Set();\n    res.moves.forEach((m, k) => {\n      // Badge on the piece cell closest to its centre, avoiding cells that later moves cover\n      // (after a line clear a later piece can sit on the same cells) and other badges.\n      const later = new Set();\n      res.moves.slice(k + 1).forEach((x) => x.cells.forEach(([r, c]) => later.add(r * 8 + c)));\n      const cr = m.cells.reduce((s, x) => s + x[0], 0) / m.cells.length;\n      const cc = m.cells.reduce((s, x) => s + x[1], 0) / m.cells.length;\n      const byDist = m.cells.slice().sort((a, b) => ((a[0] - cr) ** 2 + (a[1] - cc) ** 2) - ((b[0] - cr) ** 2 + (b[1] - cc) ** 2));\n      const key = (x) => x[0] * 8 + x[1];\n      const best = byDist.find((x) => !later.has(key(x)) && !taken.has(key(x))) || byDist.find((x) => !taken.has(key(x))) || byDist[0];\n      taken.add(key(best));\n      badge(g, grid.x + (best[1] + 0.5) * cell, grid.y + (best[0] + 0.5) * cell, cell * 0.36, COLORS[k], String(k + 1));\n      // Same number on the piece in the tray.\n      const s = det.slots[m.piece];\n      if (s) {\n        g.lineWidth = cell * 0.08; g.strokeStyle = COLORS[k];\n        roundRect(g, s.x - cell * 0.15, s.y - cell * 0.15, s.w + cell * 0.3, s.h + cell * 0.3, cell * 0.2); g.stroke();\n        badge(g, s.x + s.w / 2, Math.max(s.y - cell * 0.5, tray.y + cell * 0.3), cell * 0.34, COLORS[k], String(k + 1));\n      }\n      lines.push(`${k + 1}. ${SLOT[m.piece]} → ряд ${m.r + 1}, кол. ${m.c + 1}${m.lines ? ` (+${m.lines})` : ''}`);\n    });\n\n    // Banner with mini boards: state before each move, piece in colour, cleared lines outlined.\n    g.fillStyle = 'rgba(11,16,38,0.94)'; roundRect(g, pad, by, W - pad * 2, bannerH, cell * 0.25); g.fill();\n    const n = res.moves.length;\n    const colW = (W - pad * 2) / 3;\n    const mini = Math.min(bannerH - pad * 2, colW - pad * 2);\n    const mc = mini / 8;\n    res.moves.forEach((m, k) => {\n      const ox = pad + colW * k + (colW - mini) / 2, oy = by + (bannerH - mini) / 2;\n      const pc = new Set(m.cells.map(([r, c]) => r * 8 + c)), clr = new Set(m.clearedCells);\n      g.fillStyle = '#070a1a'; g.fillRect(ox - 2, oy - 2, mini + 4, mini + 4);\n      for (let i = 0; i < 64; i++) {\n        const x = ox + (i % 8) * mc, y = oy + Math.floor(i / 8) * mc;\n        g.fillStyle = pc.has(i) ? COLORS[k] : m.boardBefore[i] ? '#56649f' : '#1c2550';\n        g.fillRect(x + 0.5, y + 0.5, mc - 1, mc - 1);\n        if (clr.has(i)) { g.strokeStyle = '#fff27a'; g.lineWidth = Math.max(1, mc * 0.12); g.strokeRect(x + 1, y + 1, mc - 2, mc - 2); }\n      }\n      badge(g, ox, oy, mc * 1.5, COLORS[k], String(k + 1));\n    });\n    if (!res.placedAll) {\n      g.fillStyle = '#ff7a8a'; g.font = `700 ${Math.round(cell * 0.3)}px ${FONT}`;\n      g.textAlign = 'center'; g.textBaseline = 'top';\n      g.fillText('Все три не влезут — лучшее из возможного', W / 2, by + bannerH + cell * 0.05);\n      lines.push('Все три фигуры не влезут.');\n    }\n    return { img: cv.toDataURL('image/jpeg', 0.88), text: lines.join('\\n'), learnedRatio, ok: true };\n  }\n\n  root.BBOverlay = { run };\n})(typeof self !== 'undefined' ? self : this);\n\n</script></body></html>";

await main();
